"use client";

import { formatMoney, type VendorOrder } from "@mealhrs/domain";
import * as Dialog from "@radix-ui/react-dialog";
import { CalendarDays, ChevronDown, Clock3, MessageCircle, PackageCheck, Search, Truck, X } from "lucide-react";
import { useRef, useState, type MouseEvent, type MutableRefObject } from "react";
import { Button } from "@/components/ui/button";
import { Status } from "@/components/ui/status";
import styles from "./vendor-operations.module.css";

type OrderState = "immediate" | "drop";
type FulfillmentFilter = "all" | "delivery" | "pickup";
type StatusFilter = "all" | "pending_vendor" | "confirmed" | "preparing" | "ready";
type SortOrder = "newest" | "oldest" | "priority";

const tabs: readonly OrderState[] = ["immediate", "drop"];
const statusSteps = ["pending_vendor", "confirmed", "preparing", "ready"] as const;
const statusLabel = (status: string) => status.replaceAll("_", " ");
const nextAction = (status: string) => status === "pending_vendor" ? "Accept" : status === "confirmed" ? "Start preparing" : status === "preparing" ? "Mark ready" : "Dispatch";
const nextStatus = (status: string) => status === "pending_vendor" ? "confirmed" : status === "confirmed" ? "preparing" : "ready";
const priorityValue = (priority: VendorOrder["operational"]["priority"]) => priority === "attention" ? 0 : priority === "due_soon" ? 1 : 2;

export function VendorOrdersView({ immediateOrders, mealDropOrders }: Readonly<{ immediateOrders: readonly VendorOrder[]; mealDropOrders: readonly VendorOrder[] }>) {
  const [tab, setTab] = useState<OrderState>("immediate");
  const [fulfillment, setFulfillment] = useState<FulfillmentFilter>("all");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [sortOrder, setSortOrder] = useState<SortOrder>("newest");
  const [query, setQuery] = useState("");
  const [statuses, setStatuses] = useState<Record<string, string>>({});
  const [feedback, setFeedback] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(immediateOrders[0]?.id ?? null);
  const [dialogOrder, setDialogOrder] = useState<VendorOrder | null>(null);
  const tabRefs = useRef<Partial<Record<OrderState, HTMLButtonElement | null>>>({});
  const detailsTrigger = useRef<HTMLButtonElement | null>(null);
  const allOrders = [...immediateOrders, ...mealDropOrders];
  const activeIndex = tabs.indexOf(tab);
  const getStatus = (order: VendorOrder) => statuses[order.id] ?? order.orderStatus;
  const source = (tab === "immediate" ? immediateOrders : mealDropOrders).filter((order) => order.orderingMode === (tab === "immediate" ? "immediate" : "meal_drop"));
  const filteredOrders = source.filter((order) => {
    const active = !["delivered", "delivery_failed"].includes(order.fulfillmentStatus);
    const matchesFulfillment = fulfillment === "all" || order.fulfillmentMode === fulfillment;
    const matchesStatus = statusFilter === "all" || getStatus(order) === statusFilter;
    const searchable = `${order.reference} ${order.customer.name} ${order.items.map((item) => item.name).join(" ")}`.toLowerCase();
    return active && matchesFulfillment && matchesStatus && searchable.includes(query.trim().toLowerCase());
  });
  const orders = [...filteredOrders].sort((first, second) => sortOrder === "priority" ? priorityValue(first.operational.priority) - priorityValue(second.operational.priority) : (sortOrder === "newest" ? -1 : 1) * first.createdAt.localeCompare(second.createdAt));
  const selectedOrder = orders.find((order) => order.id === selectedId) ?? orders[0] ?? null;
  const mealDropContext = orders.find((order) => order.operational.mealDrop)?.operational.mealDrop;
  const summary = buildSummary(allOrders, getStatus);
  const switchTab = (next: OrderState) => { setTab(next); setFulfillment("all"); setStatusFilter("all"); setQuery(""); setSelectedId(null); };
  const selectWithArrow = (key: string) => { if (key === "ArrowLeft" || key === "ArrowRight") { const next = tabs[(activeIndex + (key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length]!; switchTab(next); tabRefs.current[next]?.focus(); } };
  const advance = (order: VendorOrder) => { const updated = nextStatus(getStatus(order)); setStatuses((current) => ({ ...current, [order.id]: updated })); setSelectedId(order.id); setFeedback(`${order.reference} is marked ${statusLabel(updated)} in this frontend preview only.`); };
  const showDetails = (order: VendorOrder, event: MouseEvent<HTMLButtonElement>) => { detailsTrigger.current = event.currentTarget; setSelectedId(order.id); if (window.matchMedia("(max-width: 980px)").matches) setDialogOrder(order); };
  const contactPreview = (order: VendorOrder) => setFeedback(`${order.customer.name} contact is a frontend preview only; no call or message was sent.`);
  return <div className={styles.ordersPage}><header className={styles.head}><p className={styles.eyebrow}>Operations</p><h1>Orders</h1><p>Manage incoming orders, preparation, and fulfilment — all in one place.</p></header>{feedback ? <p className={styles.feedback} role="status">{feedback}</p> : null}<OrderSummary summary={summary}/><OrderTabs tab={tab} tabRefs={tabRefs} onChange={switchTab} onArrow={selectWithArrow} immediateCount={immediateOrders.length} dropCount={mealDropOrders.length}/><div className={styles.workspace}><div className={styles.queue}><QueueTools tab={tab} query={query} fulfillment={fulfillment} statusFilter={statusFilter} sortOrder={sortOrder} onQuery={setQuery} onFulfillment={setFulfillment} onStatus={setStatusFilter} onSort={setSortOrder}/>{tab === "drop" && mealDropContext ? <MealDropSummary context={mealDropContext}/> : null}<section id={`vendor-orders-panel-${tab}`} role="tabpanel" aria-labelledby={`vendor-orders-tab-${tab}`} className={styles.list} aria-live="polite">{orders.length ? orders.map((order) => <OrderRow key={order.id} order={order} status={getStatus(order)} selected={selectedOrder?.id === order.id} onAdvance={advance} onDetails={showDetails}/>) : <article className={`card ${styles.empty}`}><h2>No matching {tab === "drop" ? "Meal Drop" : "immediate"} orders</h2><p>Try another status, fulfilment filter, or search term.</p></article>}</section>{tab === "immediate" && mealDropOrders.length ? <UpcomingDrop order={mealDropOrders[0]!} onView={() => switchTab("drop")}/> : null}</div><aside className={styles.detailsPanel} aria-label="Selected order details">{selectedOrder ? <OrderDetails order={selectedOrder} status={getStatus(selectedOrder)} onAdvance={advance} onContact={contactPreview}/> : <EmptyDetails/>}</aside></div><OrderDetailsDialog order={dialogOrder} status={dialogOrder ? getStatus(dialogOrder) : "pending_vendor"} onOpenChange={(open) => { if (!open) setDialogOrder(null); }} onContact={contactPreview} onAdvance={advance} onCloseAutoFocus={(event) => { event.preventDefault(); requestAnimationFrame(() => detailsTrigger.current?.focus()); }}/></div>;
}

function buildSummary(orders: readonly VendorOrder[], statusFor: (order: VendorOrder) => string) { const activeOrders = orders.filter((order) => !["delivered", "delivery_failed"].includes(order.fulfillmentStatus)); return [{ label: "New", value: activeOrders.filter((order) => statusFor(order) === "pending_vendor").length, icon: PackageCheck, tone: "new" }, { label: "Preparing", value: activeOrders.filter((order) => ["confirmed", "preparing"].includes(statusFor(order))).length, icon: Clock3, tone: "preparing" }, { label: "Ready", value: activeOrders.filter((order) => statusFor(order) === "ready").length, icon: PackageCheck, tone: "ready" }, { label: "Due soon", value: activeOrders.filter((order) => order.operational.priority === "due_soon").length, icon: Clock3, tone: "due" }, { label: "Scheduled", value: activeOrders.filter((order) => order.orderingMode === "meal_drop").length, icon: CalendarDays, tone: "scheduled" }] as const; }
function OrderSummary({ summary }: Readonly<{ summary: ReturnType<typeof buildSummary> }>) { return <section className={styles.summary} aria-label="Order status summary">{summary.map(({ label, value, icon: Icon, tone }) => <article className={styles.summaryTile} data-tone={tone} key={label}><Icon aria-hidden="true"/><span><small>{label}</small><strong>{value}</strong></span></article>)}</section>; }
function OrderTabs({ tab, tabRefs, onChange, onArrow, immediateCount, dropCount }: Readonly<{ tab: OrderState; tabRefs: MutableRefObject<Partial<Record<OrderState, HTMLButtonElement | null>>>; onChange: (tab: OrderState) => void; onArrow: (key: string) => void; immediateCount: number; dropCount: number }>) { return <div className={styles.tabs} role="tablist" aria-label="Order type">{tabs.map((candidate) => <button ref={(node) => { tabRefs.current[candidate] = node; }} key={candidate} id={`vendor-orders-tab-${candidate}`} role="tab" aria-controls={`vendor-orders-panel-${candidate}`} aria-selected={tab === candidate} tabIndex={tab === candidate ? 0 : -1} onKeyDown={(event) => onArrow(event.key)} onClick={() => onChange(candidate)}>{candidate === "immediate" ? `Immediate Orders (${immediateCount})` : `Meal Drops (${dropCount})`}</button>)}</div>; }
function QueueTools({ tab, query, fulfillment, statusFilter, sortOrder, onQuery, onFulfillment, onStatus, onSort }: Readonly<{ tab: OrderState; query: string; fulfillment: FulfillmentFilter; statusFilter: StatusFilter; sortOrder: SortOrder; onQuery: (value: string) => void; onFulfillment: (value: FulfillmentFilter) => void; onStatus: (value: StatusFilter) => void; onSort: (value: SortOrder) => void }>) { return <section className={styles.orderTools} aria-label="Order queue controls"><label className={styles.search} htmlFor="vendor-order-search"><Search aria-hidden="true"/><span className="sr-only">Search {tab === "drop" ? "Meal Drop" : "immediate"} orders</span><input id="vendor-order-search" value={query} onChange={(event) => onQuery(event.target.value)} placeholder="Search order, customer or meal"/></label><label className={styles.selectControl}><span className="sr-only">Order status</span><select value={statusFilter} onChange={(event) => onStatus(event.target.value as StatusFilter)}><option value="all">Status</option><option value="pending_vendor">New</option><option value="confirmed">Confirmed</option><option value="preparing">Preparing</option><option value="ready">Ready</option></select><ChevronDown aria-hidden="true"/></label><div className={styles.filters} aria-label="Fulfilment filter">{(["all", "delivery", "pickup"] as const).map((candidate) => <button type="button" key={candidate} aria-pressed={fulfillment === candidate} onClick={() => onFulfillment(candidate)}>{candidate === "all" ? "All fulfilment" : candidate === "delivery" ? "Delivery" : "Pickup"}</button>)}</div><label className={styles.selectControl}><span className="sr-only">Sort orders</span><select value={sortOrder} onChange={(event) => onSort(event.target.value as SortOrder)}><option value="newest">Sort: Newest</option><option value="oldest">Sort: Oldest</option><option value="priority">Sort: Priority</option></select><ChevronDown aria-hidden="true"/></label></section>; }
function MealDropSummary({ context }: Readonly<{ context: NonNullable<VendorOrder["operational"]["mealDrop"]> }>) { return <section className={`card ${styles.dropSummary}`} aria-label="Meal Drop preparation summary"><CalendarDays aria-hidden="true"/><div><strong>{context.name}</strong><p>Scheduled meal batch with a cutoff and batch prep.</p></div><dl><div><dt>Cutoff</dt><dd>{context.cutoffLabel}</dd></div><div><dt>Batch prep</dt><dd>{context.preparationWindow}</dd></div></dl><div className={styles.dropCapacity}><span>{context.capacityLabel}</span><small>{context.summary}</small></div></section>; }
function UpcomingDrop({ order, onView }: Readonly<{ order: VendorOrder; onView: () => void }>) { const context = order.operational.mealDrop; if (!context) return null; return <section className={`card ${styles.upcomingDrop}`}><CalendarDays aria-hidden="true"/><div><strong>Meal Drops — upcoming pre-orders</strong><p>Scheduled meal batches with a cutoff and batch prep.</p></div><button type="button" onClick={onView}>View all <span aria-hidden="true">→</span></button><div className={styles.upcomingDropMeta}><strong>{context.name}</strong><span>{context.summary}</span><span>{context.cutoffLabel}</span><span>{context.preparationWindow}</span></div></section>; }
function OrderRow({ order, status, selected, onAdvance, onDetails }: Readonly<{ order: VendorOrder; status: string; selected: boolean; onAdvance: (order: VendorOrder) => void; onDetails: (order: VendorOrder, event: MouseEvent<HTMLButtonElement>) => void }>) { const actionable = !["ready", "cancelled", "timed_out"].includes(status); return <article className={`card ${styles.order} ${selected ? styles.selected : ""}`} aria-current={selected ? "true" : undefined}><div className={styles.orderMain}><div className="cluster"><Status tone={status === "ready" ? "success" : order.operational.priority === "attention" ? "danger" : "warning"}>{statusLabel(status)}</Status><span className={styles.reference}>{order.reference}</span><span className={styles.mode}><Truck aria-hidden="true"/>{order.fulfillmentMode === "pickup" ? "Pickup" : "Delivery"}</span></div><h2>{order.customer.name}</h2><p className={styles.items}>{order.items.map((item) => `${item.quantity}× ${item.name}`).join(", ")}</p><div className={styles.facts}><span>{order.operational.ageLabel}</span><span>{order.fulfillmentWindow}</span><span data-payment={order.paymentStatus}>{order.operational.paymentLabel}</span></div></div><strong className={styles.total}>{formatMoney(order.total)}</strong><div className={styles.actionGroup}>{actionable ? <Button size="sm" onClick={() => onAdvance(order)}>{nextAction(status)}</Button> : <Button size="sm" variant="secondary" disabled>{statusLabel(status)}</Button>}<Button size="sm" variant="secondary" onClick={(event) => onDetails(order, event)}>Details</Button></div></article>; }
function OrderDetailsDialog({ order, status, onOpenChange, onContact, onAdvance, onCloseAutoFocus }: Readonly<{ order: VendorOrder | null; status: string; onOpenChange: (open: boolean) => void; onContact: (order: VendorOrder) => void; onAdvance: (order: VendorOrder) => void; onCloseAutoFocus: (event: Event) => void }>) { return <Dialog.Root open={Boolean(order)} onOpenChange={onOpenChange}>{order ? <Dialog.Portal><Dialog.Overlay className={styles.dialogBackdrop}/><Dialog.Content className={styles.dialog} aria-describedby="order-details-summary" onCloseAutoFocus={onCloseAutoFocus}><Dialog.Title className="sr-only">Order {order.reference}</Dialog.Title><p id="order-details-summary" className="sr-only">Order details and locally simulated fulfilment actions.</p><OrderDetails order={order} status={status} onAdvance={onAdvance} onContact={onContact} mobile/></Dialog.Content></Dialog.Portal> : null}</Dialog.Root>; }
function OrderDetails({ order, status, onAdvance, onContact, mobile = false }: Readonly<{ order: VendorOrder; status: string; onAdvance: (order: VendorOrder) => void; onContact: (order: VendorOrder) => void; mobile?: boolean }>) { const currentStep = Math.max(0, statusSteps.indexOf(status as typeof statusSteps[number])); const actionable = !["ready", "cancelled", "timed_out"].includes(status); return <div className={styles.detailContent}><header className={styles.detailHead}><div><p>Order {order.reference}</p><div className="cluster"><Status tone={status === "ready" ? "success" : "warning"}>{statusLabel(status)}</Status><span className={styles.mode}><Truck aria-hidden="true"/>{order.fulfillmentMode === "pickup" ? "Pickup" : "Delivery"}</span></div></div>{mobile ? <Dialog.Close asChild><button type="button" className={styles.close} aria-label="Close order details"><X aria-hidden="true"/></button></Dialog.Close> : null}</header><section className={styles.customer}><div><strong>{order.customer.name}</strong><span>{order.customer.phoneMasked}</span></div><Button size="sm" variant="secondary" onClick={() => onContact(order)}><MessageCircle aria-hidden="true"/>Contact</Button></section><section className={styles.detailSection}><h3>Items</h3><ul className={styles.lineItems}>{order.items.map((item) => <li key={item.id}><div><strong>{item.name}</strong><span>Qty: {item.quantity}</span>{item.selectedOptions.map((option) => <span key={`${option.name}-${option.value}`}>{option.name}: {option.value}</span>)}</div><b>{formatMoney(item.unitPrice)}</b></li>)}</ul>{order.operationalNote ? <p className={styles.note}>{order.operationalNote}</p> : null}</section><section className={styles.detailSection}><h3>{order.fulfillmentMode === "pickup" ? "Pickup details" : "Delivery address"}</h3><p className={styles.address}>{order.operational.fulfillmentDetail}</p><p className={styles.previewText}>Contact controls are preview-only; no call or message is sent.</p></section><section className={styles.detailSection}><h3>Payment</h3><dl className={styles.payment}><div><dt>Subtotal</dt><dd>{formatMoney(order.subtotal)}</dd></div><div><dt>Delivery fee</dt><dd>{formatMoney(order.deliveryFee)}</dd></div><div><dt>Service fee</dt><dd>{formatMoney(order.serviceFee)}</dd></div><div className={styles.paymentTotal}><dt>Total</dt><dd>{formatMoney(order.total)}</dd></div></dl><span className={styles.paymentBadge}>{order.operational.paymentLabel}</span></section><section className={styles.timeline}><h3>Fulfilment timeline</h3><ol>{statusSteps.map((step, index) => <li className={index <= currentStep ? styles.complete : undefined} key={step}><span aria-hidden="true"/><div><strong>{statusLabel(step)}</strong><small>{index === currentStep ? "Current preview status" : index > currentStep ? "Pending" : "Completed in preview"}</small></div></li>)}</ol></section><footer className={styles.detailFooter}>{actionable ? <Button block onClick={() => onAdvance(order)}>{nextAction(status)}</Button> : <Button block disabled>{statusLabel(status)}</Button>}<p>Frontend preview only. No real fulfilment or payment changes occur.</p></footer></div>; }
function EmptyDetails() { return <div className={styles.emptyDetails}><PackageCheck aria-hidden="true"/><h2>Select an order</h2><p>Choose an order from the queue to inspect its fulfilment details.</p></div>; }
